import functools
import sys

import pwn

pwn.context.update(arch="amd64", os="linux", terminal=["tmux", "new-window"])


def tee[T: pwn.tube](tube: T) -> T:
    if getattr(tube, "_dojotool_tee_enabled", False):
        return tube

    def enhance_method(instance, name, decorator):
        original = getattr(instance, name)
        setattr(instance, name, decorator(original))

    output = sys.__stdout__.buffer  # type: ignore sys.stdout is replaced by pwn.term

    def enhance_recv_raw(original):
        @functools.wraps(original)
        def recv_raw(numb, *args, **kwargs):
            data = original(numb, *args, **kwargs)
            if data:
                output.write(data)
                output.flush()
            return data

        return recv_raw

    enhance_method(tube, "recv_raw", enhance_recv_raw)
    setattr(tube, "_dojotool_tee_enabled", True)
    return tube
